import ghidra.app.script.GhidraScript;import java.nio.file.*;public class PluginRefs extends GhidraScript {public void run()throws Exception{StringBuilder b=new StringBuilder();var it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){var i=it.next();String s=i.toString();if(s.contains("-0x5c40(gp)")||s.contains("-0x5c3c(gp)")){var f=getFunctionContaining(i.getAddress());b.append(i.getAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\t"+s+"\n");}}for(String a:new String[]{"001a3af0","001a3ad0","001a36c0","001a3600","001a3800","001a3760"})for(var x:getReferencesTo(toAddr(a))){var f=getFunctionContaining(x.getFromAddress());b.append("ref:"+a+"\t"+x.getFromAddress()+"\t"+(f==null?"none":f.getEntryPoint())+"\n");}Files.writeString(Path.of(getScriptArgs()[0]),b.toString());}}
